/**
 * Generate paint-only dark overrides from the ordered renderer stylesheet.
 * Original light rules and all geometry remain untouched. Preserve hue for
 * green/amber/red evidence; never filter DOM nodes, images, or SVG artwork.
 * Generated bytes participate in the existing source/build fingerprint gate.
 */
import { readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import postcss from "postcss";

const COLOR = /#[\da-f]{3,8}\b|rgba?\([^()]*\)|(?<![\w-])(?:white|black|red|green|blue|orange)(?![\w-])/giu;
const VAR = /var\(\s*(--[\w-]+)/gu;
const ROLES = ["fg", "bg", "line", "shadow"];
const OUTPUT = "dark-palette.generated.css";
const NAMED = { white: "#ffffff", black: "#000000", red: "#ff0000", green: "#008000", blue: "#0000ff", orange: "#ffa500" };

function parseColor(token) {
  token = NAMED[token.toLowerCase()] ?? token;
  if (token.startsWith("#")) {
    let hex = token.slice(1);
    if (hex.length === 3 || hex.length === 4) hex = [...hex].map((c) => c + c).join("");
    if (hex.length !== 6 && hex.length !== 8) return null;
    return [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
      .concat(hex.length === 8 ? parseInt(hex.slice(6), 16) / 255 : 1);
  }
  const parts = token.match(/[\d.]+%?/gu);
  if (!parts || parts.length < 3 || parts.length > 4) return null;
  const rgb = parts.slice(0, 3).map((p) => parseFloat(p) / (p.endsWith("%") ? 100 : 255));
  const alpha = parts[3] ? parseFloat(parts[3]) / (parts[3].endsWith("%") ? 100 : 1) : 1;
  return [...rgb, alpha];
}

function hsl([r, g, b]) {
  const max = Math.max(r, g, b), min = Math.min(r, g, b), d = max - min;
  const l = (max + min) / 2;
  let h = 0;
  if (d) h = (max === r ? (g - b) / d + (g < b ? 6 : 0) : max === g ? (b - r) / d + 2 : (r - g) / d + 4) * 60;
  return [h, d ? d / (1 - Math.abs(2 * l - 1)) : 0, l];
}

function rgb(h, s, l) {
  const a = s * Math.min(l, 1 - l);
  return [0, 8, 4].map((n) => {
    const k = (n + h / 30) % 12;
    return Math.round(255 * (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))));
  });
}

export function darkColor(token, role) {
  const color = parseColor(token);
  if (!color) return token;
  const [h, s, l] = hsl(color);
  let out;
  let alpha = color[3];
  if (role === "shadow") {
    out = l > .8 ? [210, 220, 240] : [0, 0, 0];
    if (l > .8) alpha *= .06;
  } else if (role === "fg") {
    // Neutral hierarchy remains legible; colored evidence retains its hue.
    out = s < .18 ? rgb(220, .16, l > .94 || l < .35 ? .92 : .74)
      : rgb(h, Math.min(s, .78), l > .94 ? .94 : l < .35 ? .85 : .76);
  } else if (role === "bg") {
    // Pale surfaces become elevated charcoal; saturated fills stay tinted.
    const chroma = Math.max(...color.slice(0, 3)) - Math.min(...color.slice(0, 3));
    const neutral = chroma < .04;
    const saturation = neutral ? .19 : l > .8 ? Math.min(chroma * 1.8, .32) : Math.min(s * .6, .4);
    out = rgb(neutral ? 220 : h, saturation, l > .8 ? .125 + (l - .8) * .18 : .12 + l * .12);
  } else {
    out = rgb(s < .15 ? 220 : h, Math.min(s, .35), s > .4 && l < .75 ? .42 : .26);
  }
  return alpha >= .999 ? `#${out.map((n) => n.toString(16).padStart(2, "0")).join("")}`
    : `rgb(${out.join(" ")} / ${Number(alpha.toFixed(4))})`;
}

function paintRole(prop) {
  if (/^(?:color|fill|stroke|stop-color|accent-color|caret-color|-webkit-text-fill-color|text-decoration-color|text-emphasis-color)$/u.test(prop)) return "fg";
  if (/^background(?:-color|-image)?$/u.test(prop)) return "bg";
  if (/^(?:box-shadow|text-shadow|filter)$/u.test(prop)) return "shadow";
  if (/^(?:border(?:-(?:top|right|bottom|left|inline|block|inline-start|inline-end|block-start|block-end))?(?:-color)?|outline(?:-color)?|column-rule(?:-color)?)$/u.test(prop)) return "line";
  return null;
}

function variableName(name, role) { return `--ui-dark-${role}-${name.slice(2)}`; }

function convert(value, role, variables) {
  // URL payloads are opaque artwork and must never be recolored.
  const urls = [];
  value = value.replace(/url\([^)]*\)/giu, (url) => { urls.push(url); return `__ASSET_${urls.length - 1}__`; });
  value = value.replace(COLOR, (token) => darkColor(token, role));
  value = value.replace(VAR, (full, name) => variables.has(name) ? `var(${variableName(name, role)}` : full);
  return value.replace(/__ASSET_(\d+)__/gu, (_, index) => urls[Number(index)]);
}

function scope(selector) {
  // :where adds zero specificity, preserving all original state/hover ordering.
  if (/^:root\b/u.test(selector)) return selector.replace(/^:root/u, ':root:where([data-ui-mode="dark"])');
  if (/^html\b/u.test(selector)) return selector.replace(/^html/u, 'html:where([data-ui-mode="dark"])');
  return `:where(:root[data-ui-mode="dark"]) ${selector}`;
}

export function createDarkPalette(css) {
  const source = postcss.parse(css);
  const variables = new Set();
  source.walkDecls((decl) => {
    if (decl.prop.startsWith("--") && [...decl.value.matchAll(COLOR)].length) variables.add(decl.prop);
  });
  // Resolve color aliases without interpreting non-color geometry variables.
  let previousSize;
  do {
    previousSize = variables.size;
    source.walkDecls((decl) => {
      if (decl.prop.startsWith("--") && [...decl.value.matchAll(VAR)].some((match) => variables.has(match[1]))) variables.add(decl.prop);
    });
  } while (previousSize !== variables.size);

  const copy = (nodes) => nodes.flatMap((node) => {
    if (node.type === "atrule" && /^(media|supports|container|layer)$/u.test(node.name)) {
      const children = copy(node.nodes ?? []);
      return children.length ? [postcss.atRule({ name: node.name, params: node.params, nodes: children })] : [];
    }
    if (node.type !== "rule" || (/data-ui-mode="(?:light|dark)"/u.test(node.selector))) return [];
    const declarations = [];
    for (const decl of node.nodes ?? []) {
      if (decl.type !== "decl") continue;
      if (variables.has(decl.prop)) {
        for (const role of ROLES) declarations.push(postcss.decl({ prop: variableName(decl.prop, role), value: convert(decl.value, role, variables), important: decl.important }));
        continue;
      }
      const role = paintRole(decl.prop);
      if (!role) continue;
      let prop = decl.prop, value = convert(decl.value, role, variables);
      if (role === "line" && !prop.endsWith("color")) {
        // Copy only paint, NEVER reintroduce old border widths or outline geometry.
        const color = decl.value.match(/var\([^)]*\)|#[\da-f]{3,8}\b|rgba?\([^)]*\)|(?<![\w-])(?:white|black|transparent|currentColor)(?![\w-])/iu)?.[0];
        if (!color) continue;
        prop += "-color";
        value = convert(color, role, variables);
      }
      if (decl.prop === "filter" && !decl.value.includes("drop-shadow")) continue;
      declarations.push(postcss.decl({ prop, value, important: decl.important }));
    }
    return declarations.length ? [postcss.rule({ selector: node.selectors.map(scope).join(",\n"), nodes: declarations })] : [];
  });
  const result = postcss.root({ nodes: copy(source.nodes) });
  // Style files only: no images, no layout declarations, no JS at runtime.
  return `/* Generated by scripts/generate-dark-palette.mjs; do not edit. */\n${result.toString()}\n` +
    ':root[data-ui-mode="dark"] { color-scheme: dark; --ink: #e7ebf2; --muted: #a5aebd; --line: #353d4b; --surface: #202630; --canvas: #13171f; }\n' +
    ':root[data-ui-mode="dark"] body { background: #13171f; color: #e7ebf2; }\n' +
    ':root[data-ui-mode="dark"] .appearance-mode > input::before { background: #f8fafc; }\n' +
    ':root[data-ui-mode="dark"] .sales-trend-line.is-current { stroke: #f4b340; }\n';
}

export async function generateDarkPalette(root = resolve(dirname(fileURLToPath(import.meta.url)), "../src/renderer/src/styles")) {
  const entry = await readFile(resolve(root, "index.css"), "utf8");
  const paths = [...entry.matchAll(/@import "\.\/([^"]+)";/gu)].map((m) => m[1]).filter((name) => name !== OUTPUT);
  const css = (await Promise.all(paths.map((name) => readFile(resolve(root, name), "utf8")))).join("").replace(/\r\n?/gu, "\n");
  const result = createDarkPalette(css);
  await writeFile(resolve(root, OUTPUT), result);
  return result;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) await generateDarkPalette();
